// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader Protocol = 1 << iota
	Framed
	HTTP
	GRPC
	HESSIAN2
	STREAMING

	TTHeaderFramed    = TTHeader | Framed
	TTHeaderStreaming Protocol = 64
	GRPCStreaming     = 128
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	// Handle known single values first
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case STREAMING:
		return "STREAMING"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Handle composite values - build pipe-separated string in ascending bit order
	var flags []string
	if tp&TTHeader != 0 {
		flags = append(flags, "TTHeader")
	}
	if tp&Framed != 0 {
		flags = append(flags, "Framed")
	}
	if tp&HTTP != 0 {
		flags = append(flags, "HTTP")
	}
	if tp&GRPC != 0 {
		flags = append(flags, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		flags = append(flags, "HESSIAN2")
	}
	if tp&STREAMING != 0 {
		flags = append(flags, "STREAMING")
	}

	if len(flags) > 0 {
		result := flags[0]
		for i := 1; i < len(flags); i++ {
			result += "|" + flags[i]
		}
		return result
	}

	return Unknown
}
