{"path": "task/workspace/pkg/endpoint/endpoint.go", "start": 60, "lines": 40, "offset": 0, "total_lines": 99, "content": "// UnaryEndpoint is an alias for Endpoint representing unary RPC calls.
type UnaryEndpoint Endpoint

// UnaryMiddleware wraps a UnaryEndpoint with additional logic.
type UnaryMiddleware func(next UnaryEndpoint) UnaryEndpoint

// UnaryMiddlewareBuilder builds a UnaryMiddleware with information from a context.
type UnaryMiddlewareBuilder func(ctx context.Context) UnaryMiddleware

// UnaryChain connects unary middlewares into one middleware.
func UnaryChain(mws ...UnaryMiddleware) UnaryMiddleware {
	return func(next UnaryEndpoint) UnaryEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// ToMiddleware converts UnaryMiddleware to generic Middleware.
func (mw UnaryMiddleware) ToMiddleware() Middleware {
	return func(next Endpoint) Endpoint {
		return Endpoint(mw(UnaryEndpoint(next)))
	}
}

// ToUnaryMiddleware converts generic Middleware to UnaryMiddleware.
func (mw Middleware) ToUnaryMiddleware() UnaryMiddleware {
	return func(next UnaryEndpoint) UnaryEndpoint {
		return UnaryEndpoint(mw(Endpoint(next)))
	}
}

type mwCtxKeyType int

// Keys for components attached to the context for a middleware builder.
const (
	CtxEventBusKey mwCtxKeyType = iota
	CtxEventQueueKey
)
